import { MakeLogicType, afterMount, connect, kea, path, selectors } from 'kea'
import { loaders } from 'kea-loaders'

import api from 'lib/api'
import { ApprovalActionKey } from 'scenes/approvals/utils'
import { teamLogic } from 'scenes/teamLogic'
import { userLogic } from 'scenes/userLogic'

import { ApprovalPolicy, AvailableFeature } from '~/types'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface approvalsGateLogicValues {
    currentTeamIdStrict: number | string // teamLogic
    hasAvailableFeature: (feature: AvailableFeature, currentUsage?: number | undefined) => boolean // userLogic
    activePolicies: ApprovalPolicy[]
    activePoliciesLoading: boolean
    isApprovalRequired: (actionKey: string) => boolean
    isApprovalsFeatureEnabled: boolean
    isExperimentOperationApprovalRequired: (actionKey: string) => boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface approvalsGateLogicActions {
    loadActivePolicies: () => any
    loadActivePoliciesFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadActivePoliciesSuccess: (
        activePolicies: ApprovalPolicy[],
        payload?: any
    ) => {
        activePolicies: ApprovalPolicy[]
        payload?: any
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface approvalsGateLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        isApprovalsFeatureEnabled: (
            hasAvailableFeature: (feature: AvailableFeature, currentUsage?: number | undefined) => boolean
        ) => boolean
        isApprovalRequired: (
            isApprovalsFeatureEnabled: boolean,
            activePolicies: ApprovalPolicy[]
        ) => (actionKey: string) => boolean
        isExperimentOperationApprovalRequired: (
            isApprovalRequired: (actionKey: string) => boolean,
            activePolicies: ApprovalPolicy[]
        ) => (actionKey: string) => boolean
    }
}

export type approvalsGateLogicType = MakeLogicType<
    approvalsGateLogicValues,
    approvalsGateLogicActions,
    Record<string, any>,
    approvalsGateLogicMeta
>

export const approvalsGateLogic = kea<approvalsGateLogicType>([
    path(['lib', 'approvals', 'approvalsGateLogic']),

    connect(() => ({
        values: [userLogic, ['hasAvailableFeature'], teamLogic, ['currentTeamIdStrict']],
    })),

    loaders(({ values }) => ({
        activePolicies: [
            [] as ApprovalPolicy[],
            {
                loadActivePolicies: async () => {
                    if (!values.hasAvailableFeature(AvailableFeature.APPROVALS)) {
                        return []
                    }

                    try {
                        // nosemgrep: prefer-codegen-api -- Legacy raw API call with a hand-written URL and an unchecked response type. Use approvalPoliciesList() from 'products/platform_features/frontend/generated/api' instead.
                        const response = await api.get(`api/projects/${values.currentTeamIdStrict}/approval_policies/`)
                        return (response.results || []).filter((p: ApprovalPolicy) => p.enabled)
                    } catch {
                        return []
                    }
                },
            },
        ],
    })),

    selectors({
        isApprovalsFeatureEnabled: [
            (s) => [s.hasAvailableFeature],
            (hasAvailableFeature: (feature: AvailableFeature, currentUsage?: number | undefined) => boolean): boolean =>
                hasAvailableFeature(AvailableFeature.APPROVALS),
        ],

        isApprovalRequired: [
            (s) => [s.isApprovalsFeatureEnabled, s.activePolicies],
            (isEnabled: boolean, policies: ApprovalPolicy[]) =>
                (actionKey: string): boolean => {
                    if (!isEnabled) {
                        return false
                    }
                    return policies.some((p: ApprovalPolicy) => p.action_key === actionKey && p.enabled)
                },
        ],

        // Experiment operations borrow an "Update experiment" policy with no conditions. The list omits
        // experiment policies before the organization scopes policies by flag owner, so this is false then.
        isExperimentOperationApprovalRequired: [
            (s) => [s.isApprovalRequired, s.activePolicies],
            (isApprovalRequired: (actionKey: string) => boolean, policies: ApprovalPolicy[]) =>
                (actionKey: string): boolean =>
                    isApprovalRequired(actionKey) ||
                    (isApprovalRequired(ApprovalActionKey.EXPERIMENT_UPDATE) &&
                        policies.some(
                            (p: ApprovalPolicy) =>
                                p.enabled &&
                                p.action_key === ApprovalActionKey.EXPERIMENT_UPDATE &&
                                Object.keys(p.conditions ?? {}).length === 0
                        )),
        ],
    }),

    afterMount(({ actions }) => {
        actions.loadActivePolicies()
    }),
])
